// The Worker entry: filming videos stream straight from R2 (see src/lib/server/video.ts);
// everything else goes to the Next.js app built by OpenNext.

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as nextApp } from "./.open-next/worker.js";
import { serveVideo } from "./src/lib/server/video";

export default {
  fetch(req, env, ctx) {
    if (req.method === "GET" && new URL(req.url).pathname.startsWith("/media/captures/")) {
      return serveVideo(req, env.MEDIA, env.MEDIA_LINK_SECRET);
    }
    return nextApp.fetch(req, env, ctx);
  },
} satisfies ExportedHandler<CloudflareEnv>;
